SELECT b.name,b.created_at,b.booking_start_date,b.booking_end_date,b.booking_status,b.approval_status,b.payment_status AS booking_payment_status,b.requested_by,b.payment,f.name AS facility_name,p.payment_id,p.payment_status,p.created_at AS payment_created_at,(SELECT jsonb_agg(jsonb_build_object('request_id',r.request_id,'created_at',r.created_at,'status',r.status)) FROM public."SSP_Facility_Booking_Request" r WHERE r.payment=b.payment) AS requests FROM public."SSP_Facility_Booking" b LEFT JOIN public."SSP_Payment" p ON p.pay_rec_id=b.payment LEFT JOIN public."SSP_Facility" f ON f.id=b.facility ORDER BY b.created_at DESC NULLS LAST LIMIT 5;
SELECT t.tgname,t.tgrelid::regclass::text AS table_name,pg_get_triggerdef(t.oid) AS trigger_definition,pg_get_functiondef(t.tgfoid) AS function_definition FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgrelid IN ('public."SSP_Payment"'::regclass,'public."SSP_Facility_Booking_Request"'::regclass,'public."SSP_Facility_Booking"'::regclass);
